style.css:
@-moz-document domain("facebook.com") {
/* ===== Colors ===== */
  :root, .__fb-light-mode, .__fb-dark-mode {
    --web-wash: transparent !important;
    --surface-background: rgba(12, 12, 14, 0.85) !important;
    --card-background: rgba(255, 255, 255, 0.05) !important;
    --comment-background: rgba(255, 255, 255, 0.08) !important;
    --primary-text: #f2f2f2 !important;
    --secondary-text: #a8a8ad !important;
    --primary-icon: #f2f2f2 !important;
    --secondary-icon: #a8a8ad !important;
    --accent: #dfe6ee !important;
    --primary-button-background: #3a3a40 !important;
    --divider: rgba(255, 255, 255, 0.08) !important;
    --media-inner-border: transparent !important;
    --hover-overlay: rgba(255, 255, 255, 0.07) !important;
  }

  /* ===== Background ===== */
  html, body {
    background:
      radial-gradient(circle at 20% 0%, rgba(255, 255, 255, 0.08), transparent 40%),
      radial-gradient(circle at 80% 100%, rgba(255, 255, 255, 0.05), transparent 45%),
      linear-gradient(160deg, #0a0a0b 0%, #151517 50%, #050506 100%) fixed !important;
  }

  /* ===== Top bar ===== */
  [role="banner"] {
    background: linear-gradient(180deg, #1c1c1f 0%, #0d0d0f 100%) !important;
    backdrop-filter: none !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.10) !important;
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.12),
      0 4px 18px rgba(0, 0, 0, 0.6) !important;
    z-index: 9999 !important;
  }

  /* Glow on active top tab */
  [role="banner"] [aria-current="page"] {
    filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.7)) !important;
  }

  /* ===== Right sidebar: no big box ===== */
  [role="complementary"],
  [role="complementary"] > div {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* ===== Feed posts only ===== */
  [role="main"] [role="feed"] > div {
    margin-bottom: 14px !important;
  }
  [role="main"] [role="feed"] > div > div > div > div {
    border-radius: 18px !important;
  }
  [role="main"] [role="feed"] > div > div > div > div > div {
    background: linear-gradient(165deg, rgba(255,255,255,0.09) 0%, rgba(255,255,255,0.02) 50%, rgba(0,0,0,0.2) 100%) !important;
    border: 1px solid rgba(255, 255, 255, 0.10) !important;
    border-radius: 18px !important;
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.18),
      0 10px 30px rgba(0, 0, 0, 0.55) !important;
    overflow: hidden !important;
    transition: transform 0.25s ease, box-shadow 0.25s ease !important;
  }

  /* Posts lift on hover */
  [role="main"] [role="feed"] > div > div > div > div > div:hover {
    transform: translateY(-3px) !important;
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.25),
      0 16px 40px rgba(0, 0, 0, 0.7) !important;
  }

  /* Comments stay flat inside posts */
  [role="feed"] [role="article"] [role="article"] {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }

  /* Rounded photos */
  [role="feed"] img[referrerpolicy] {
    border-radius: 10px !important;
  }

  /* ===== Left menu hover pill ===== */
  [role="navigation"] a[role="link"]:hover,
  [role="navigation"] div[role="button"]:hover {
    background: rgba(255, 255, 255, 0.08) !important;
    border-radius: 12px !important;
  }

  /* ===== Stories: rounded ===== */
  [aria-label*="tories"] a,
  [aria-label*="tories"] div[role="button"] {
    border-radius: 14px !important;
    overflow: hidden !important;
  }

  /* ===== Inputs ===== */
  input[type="search"],
  [role="main"] [contenteditable="true"] {
    background: rgba(255, 255, 255, 0.07) !important;
    border: 1px solid rgba(255, 255, 255, 0.12) !important;
    border-radius: 20px !important;
  }

  /* ===== Chat window: no boxed messages ===== */
  [role="dialog"] [role="row"],
  [role="dialog"] [role="gridcell"] {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* ===== Smooth buttons ===== */
  div[role="button"], a[role="link"] {
    transition: background 0.2s ease, transform 0.15s ease !important;
  }
  div[role="button"]:active {
    transform: scale(0.97) !important;
  }

  /* ===== Text selection ===== */
  ::selection {
    background: rgba(255, 255, 255, 0.25);
    color: #fff;
  }

  /* ===== Chrome scrollbar ===== */
  ::-webkit-scrollbar { width: 8px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, #e6e6e6, #6b6b70);
    border-radius: 10px;
  }
}
